CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, surname TEXT NOT NULL, age INTEGER, active INTEGER, bio TEXT, score REAL);
CREATE TABLE IF NOT EXISTS products (sku TEXT PRIMARY KEY, name TEXT NOT NULL, price INTEGER, stock INTEGER, category TEXT) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS orders (order_id INTEGER, item_id INTEGER, quantity INTEGER, total REAL, status TEXT, PRIMARY KEY (order_id, item_id));
